from pathlib import Path

import pytest

NOTES_DIR: Path = Path("notes")


def read_note(name: str) -> str:
    """Return the text of note `name` inside NOTES_DIR.

    Returns "" when the file is missing or unreadable. Any name that would
    resolve outside NOTES_DIR (absolute paths, "..", symlinks leaving the
    directory) also yields "" and is never opened.
    """
    try:
        base = NOTES_DIR.resolve()
        target = (NOTES_DIR / name).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError):
        return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "notes").mkdir()
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    return tmp_path


def test_reads_existing_note(workdir: Path) -> None:
    (workdir / "notes" / "todo.txt").write_text("buy milk", encoding="utf-8")
    assert read_note("todo.txt") == "buy milk"


def test_missing_note_is_empty(workdir: Path) -> None:
    assert read_note("nope.txt") == ""


def test_parent_traversal_is_blocked(workdir: Path) -> None:
    assert read_note("../secret.txt") == ""


def test_nested_traversal_is_blocked(workdir: Path) -> None:
    assert read_note("sub/../../secret.txt") == ""


def test_absolute_path_is_blocked(workdir: Path) -> None:
    assert read_note(str(workdir / "secret.txt")) == ""


def test_symlink_escaping_notes_is_blocked(workdir: Path) -> None:
    (workdir / "notes" / "link.txt").symlink_to(workdir / "secret.txt")
    assert read_note("link.txt") == ""


def test_directory_is_empty(workdir: Path) -> None:
    (workdir / "notes" / "folder").mkdir()
    assert read_note("folder") == ""


def test_empty_name_is_empty(workdir: Path) -> None:
    assert read_note("") == ""


def test_nul_byte_name_is_empty(workdir: Path) -> None:
    assert read_note("a\x00b") == ""
